func catalogName(id, modelName string) string {
	entry, ok, err := catalog.Identify(id, modelName)
	switch {
	case err != nil:
		return id
	case !ok:
		return "None"
	case id == "":
		return entry.Name + " (matched by model ID)"
	default:
		return entry.Name
	}
}

func modelDefaultLabel(isDefault bool) string {
	if isDefault {
		return "Yes"
	}
	return "No"
}

func modelFormTitle(name string) string {
	if name == "" {
		return "New model"
	}
	return name
}

var _ = templruntime.GeneratedTemplate
